/*
 * FRAMEBUFFER - draw off-screen, show it in one go.
 *
 * MMBasic's Draw.c cmd_framebuffer:
 *
 *   FRAMEBUFFER CREATE            make the F buffer, blank
 *   FRAMEBUFFER LAYER             make the layer, blank
 *   FRAMEBUFFER WRITE N | F | L   send drawing to the screen, the
 *                                 buffer, or the layer
 *   FRAMEBUFFER COPY s, d [, B]   s and d each N, F or L; B waits for
 *                                 the top of the frame first
 *   FRAMEBUFFER MERGE [colour]    the layer over F, onto the screen,
 *                                 skipping the transparent index
 *   FRAMEBUFFER CLOSE [F | L]     give one back
 *   FRAMEBUFFER WAIT              wait for the top of the frame
 *
 * The rules - what is an error, and when - are common to every target,
 * so a program behaves the same under the host gates as on the board.
 * Only the five hw hooks below differ, and on the host they do nothing:
 * a translated program still RUNS there, it just has nowhere to draw.
 */
#define MM_FB_N 0
#define MM_FB_F 1
#define MM_FB_L 2                       /* the layer - MMBasic FRAMEBUFFER LAYER */

/*	Two off-screen buffers now, created and closed separately as
 *	MMBasic creates and closes them: FRAMEBUFFER CREATE and CLOSE F for
 *	one, FRAMEBUFFER LAYER and CLOSE L for the other.  MERGE needs
 *	both, which is what MMBasic's own two NULL tests say. */
static int mm_fb_made;                  /* CREATE done, CLOSE not yet */
static int mm_fb_made_l;                /* LAYER done, CLOSE L not yet */
static int mm_fb_wr = MM_FB_N;          /* where drawing goes now */

#if defined(MM_FCC) || defined(__FUZIX__) || defined(MM_PC3)

#define MM_GFXIOC_FBSEL    0x0016
#define MM_GFXIOC_FBOPEN   0x0018
/*	0x0017 was FBCOPY when a copy could only go one of two ways.  The
 *	layer made that three buffers, so the argument became
 *	(src << 4) | dst and the NUMBER changed with it: a mismatched
 *	runtime and kernel now get EINVAL instead of copying the wrong way
 *	round in silence.  0x0017 is retired, not reused. */
#define MM_GFXIOC_FBCOPY2  0x0033
#define MM_GFXIOC_MERGE    0x0034
#define MM_GFXIOC_VSYNC    0x0019
#define MM_GFXIOC_VSYNCTRY 0x003E

/* The layer is owned: one process at a time holds it, and the kernel
 * takes it back on exit, exec or a mode change.  So CREATE is a claim
 * that can fail - no PSRAM on this board, or another program has it -
 * which is why this one returns a value and the rest do not. */
static int mm_fb_open_hw(int claim, int which)
{
    if (mm_gfx_open() < 0)
        return -1;
    return ioctl(mm_gfx_fd, MM_GFXIOC_FBOPEN,
                 (void *)(long)((which << 8) | claim));
}

static void mm_fb_sel_hw(int which)
{
    if (mm_gfx_open() >= 0)
        ioctl(mm_gfx_fd, MM_GFXIOC_FBSEL, (void *)(long)which);
}

static void mm_fb_copy_hw(int src, int dst)
{
    if (mm_gfx_open() >= 0)
        ioctl(mm_gfx_fd, MM_GFXIOC_FBCOPY2,
              (void *)(long)((src << 4) | dst));
}

/*
 * Wait for the top of blanking WITHOUT holding the processor.
 *
 * The kernel is the only thing that can see the scanline, but it does
 * not preempt inside a syscall - so the old "spin in the kernel until
 * v_scanline is 0" stopped every other process for up to a frame,
 * 16.7ms, every time a program merged.  With a MOD player running that
 * is audible: its queue drains between merges and the music pulses.
 *
 * GFXIOC_VSYNCTRY does the same spin BOUNDED, so this loops on it and
 * is back in user mode - preemptible, tick and all - between the
 * slices.  2ms a slice is nine tries to cover a frame: nine crossings
 * at 2us against 16.7ms of somebody else's CPU handed back.
 *
 * Bounded overall for the same reason the kernel's version was: if the
 * scanout ever stops, a program must not hang waiting for a raster
 * that is not coming.
 */
static void mm_fb_vsync_wait(void)
{
    int i;

    if (mm_gfx_open() < 0)
        return;
    for (i = 0; i < 32; i++)
        if (ioctl(mm_gfx_fd, MM_GFXIOC_VSYNCTRY, (void *)2000L) != 0)
            return;
}

static int mm_fb_merge_hw(int colour)
{
    if (mm_gfx_open() < 0)
        return -1;
    /* The kernel merge no longer waits: the wait is here, where the
       program can be taken off the processor while it happens. */
    mm_fb_vsync_wait();
    return ioctl(mm_gfx_fd, MM_GFXIOC_MERGE, (void *)(long)colour);
}

static void mm_fb_wait_hw(void)
{
    mm_fb_vsync_wait();
}

/* Flood whatever is currently being drawn on.  One rectangle: the
 * kernel fills whole bytes at a time, so this is a memset in disguise
 * and costs one crossing however big the screen is. */
static void mm_fb_paint_hw(MMINTEGER rgb)
{
    struct mm_gfx_info gi;

    if (mm_gfx_open() < 0 || ioctl(mm_gfx_fd, MM_GFXIOC_INFO, &gi) < 0)
        return;
    mm_gfx_setcol(rgb);
    mm_gfx_rect(0, 0, (int)gi.width - 1, (int)gi.height - 1);
}

/* CREATE hands back a blank buffer, as MMBasic's memset does.  The
 * layer is static here and outlives the program that used it, so
 * without this a new program would start with the last one's picture. */
static void mm_fb_clear_hw(int which)
{
    mm_fb_sel_hw(which);
    mm_fb_paint_hw(0);
    mm_fb_sel_hw(mm_fb_wr);             /* back where the program was */
}

#else   /* host: the rules still apply, there is just nothing behind them */

static int mm_fb_open_hw(int claim, int w) { (void)claim; (void)w; return 0; }
static void mm_fb_sel_hw(int which)     { (void)which; }
static void mm_fb_copy_hw(int s, int d) { (void)s; (void)d; }
static int mm_fb_merge_hw(int colour)   { (void)colour; return 0; }
static void mm_fb_wait_hw(void)         {}
static void mm_fb_clear_hw(int which)   { (void)which; }
static void mm_fb_paint_hw(MMINTEGER c) { (void)c; }

#endif

/* CLS while drawing off-screen is a flood of the buffer in the
 * background colour, not the console's clear-screen - which would wipe
 * the picture that is showing and leave the buffer accumulating.  On
 * the screen it is the console's own, so the cursor and the colour
 * tiles are reset too; that is what returning 0 asks for. */
/*
 * CLS clears whatever is being DRAWN on - MMBasic's cmd_cls, which
 * floods WriteBuf.
 *
 * In a graphics mode that is always the write target, screen or
 * off-screen buffer, and never the console: sending the console an
 * ANSI clear here left the escape on the serial port and cleared the
 * console's idea of the screen while PRINT was drawing glyphs into the
 * target - the same split path PRINT used to have.  The text cursor
 * goes back to the origin with it, as MMBasic's CurrentX/Y do.
 *
 * On the text console it stays the console's own clear, which also
 * resets the cursor and the colour tiles - things a rectangle over the
 * framebuffer would not do.
 *
 * rgb is MMBasic's optional colour, and MM_CUR - what a bare CLS passes
 * - means the background COLOUR set, which is the interpreter's
 * gui_bcolour default.
 */
static int mm_fb_cls(MMINTEGER rgb)
{
    if (!mm_gon && mm_fb_wr == MM_FB_N)
        return 0;                       /* the console's job */
    mm_gn = 0;                          /* drop anything half-collected */
    mm_fb_paint_hw(rgb == MM_CUR ? mm_bg() : rgb);
    mm_gx = mm_gy = 0;
    return 1;
}

/* A mode change took it away underneath us (see the forward declaration
 * near MODE).  Nothing to release: the kernel has already dropped it. */
static void mm_fb_forget(void)
{
    mm_fb_made = 0;
    mm_fb_wr = MM_FB_N;
}

/*	which is MM_FB_F for FRAMEBUFFER CREATE and MM_FB_L for
 *	FRAMEBUFFER LAYER.  Two buffers, created independently, as
 *	MMBasic creates them - and each hands back a BLANK one, because
 *	both are static here and outlive the program that used them. */
void mm_fb_create(MMINTEGER which)
{
    int *made = (which == MM_FB_L) ? &mm_fb_made_l : &mm_fb_made;

    mm_pix_drain();             /* a layer claim must not strand queued pixels */
    if (*made) {
        mm_error(which == MM_FB_L ? "Layer already exists"
                                  : "Framebuffer already exists");
        return;
    }
    if (mm_fb_open_hw(1, (int)which) < 0) {
        mm_error(which == MM_FB_L ? "Layer not available"
                                  : "Framebuffer not available");
        return;
    }
    *made = 1;
    mm_fb_clear_hw((int)which);
}

/* Closing one that was never created is deliberately quiet - MMBasic's
 * closeframebuffer simply finds nothing to free - because a program
 * that tidies up unconditionally at the end is the normal shape. */
void mm_fb_close(MMINTEGER which)
{
    mm_pix_drain();             /* as mm_fb_create */
    mm_fb_open_hw(0, (int)which);   /* drops the claim AND the selection */
    if (which == MM_FB_L)
        mm_fb_made_l = 0;
    else
        mm_fb_forget();
    if (mm_fb_wr == (int)which)
        mm_fb_wr = MM_FB_N;
}

void mm_fb_write(MMINTEGER which)
{
    mm_pix_drain();             /* pixels land in the layer that was selected when they were queued */
    if (which == MM_FB_F && !mm_fb_made) {
        mm_error("Frame buffer not created");
        return;
    }
    if (which == MM_FB_L && !mm_fb_made_l) {
        mm_error("Layer not created");
        return;
    }
    mm_fb_sel_hw((int)which);
    mm_fb_wr = (int)which;
}

/* Where drawing goes right now (0 N, 1 F, 2 L).  mmb_blit.h's
 * FRAMEBUFFER and FLASH forms switch the target to work and must put
 * it back where the program had it; this is "where it had it". */
MMINTEGER mm_fb_cur(void)
{
    return mm_fb_wr;
}

void mm_fb_copy(MMINTEGER src, MMINTEGER dst, MMINTEGER wait)
{
    mm_pix_drain();             /* a copy is a snapshot: what was drawn must be in it */
    if (src == dst) {
        mm_error("FRAMEBUFFER COPY source and destination are the same");
        return;
    }
    /*	Either end may be the layer now, so what has to exist is
     *	whatever this copy actually names. */
    if ((src == MM_FB_F || dst == MM_FB_F) && !mm_fb_made) {
        mm_error("Frame buffer not created");
        return;
    }
    if ((src == MM_FB_L || dst == MM_FB_L) && !mm_fb_made_l) {
        mm_error("Layer not created");
        return;
    }
    /*
     * ,B waits for vertical blanking, and ONLY when the destination is
     * the physical display.
     *
     * The wait exists because the destination is the buffer core1 is
     * DMAing out: writing it part way down a frame shows the top of the
     * new picture and the bottom of the old one.  A copy into F or the
     * layer touches nothing being scanned out, so there is nothing to
     * tear and nothing to wait for - waiting there would cost a frame
     * for no reason, which on a program copying every frame is half its
     * budget.  The reference reaches the wait only down its "copying to
     * the real display" arm too (FrameBuffer.c:1197 cmd_framebuffer;
     * the plain buffer-to-buffer case is one memcpy).
     */
    if (wait && dst == MM_FB_N)
        mm_fb_wait_hw();
    mm_fb_copy_hw((int)src, (int)dst);
}

/*
 *	FRAMEBUFFER MERGE [colour] - the layer over F, onto the screen,
 *	skipping the transparent index (0-15, default 0).
 *
 *	MMBasic's TFT model exactly: neither source is touched, so a
 *	program can move something about in the layer and merge again
 *	without redrawing the background underneath it.
 *
 *	The kernel does the compositing, and HOW depends on the depth of
 *	the mode: per nibble in MODE 2, where 4bpp packs two pixels to a
 *	byte, but per BIT in MODE 1, which is the one-bit console.  Keying
 *	nibbles there would read eight pixels as two 4-bit numbers and
 *	still draw a picture.  The range check below is MMBasic's 0-15
 *	whatever the mode, as MMBasic's is.
 */
void mm_fb_merge(MMINTEGER colour)
{
    mm_pix_drain();             /* a merge is a snapshot, as a copy is */
    if (colour < 0 || colour > 15) {
        mm_error("Number out of bounds");
        return;
    }
    if (!mm_fb_made) {
        mm_error("Frame buffer not created");
        return;
    }
    if (!mm_fb_made_l) {
        mm_error("Layer not created");
        return;
    }
    if (mm_fb_merge_hw((int)colour) < 0)
        mm_error("Framebuffer merge failed");
}

void mm_fb_wait(void)
{
    mm_pix_drain();             /* a program that waits for blanking expects its drawing to be there */
    mm_fb_wait_hw();
}
